import pandas as pd
import numpy as np

# Load data
transport_df = pd.read_csv('chunks_csv/moran_local_2023_transport.csv')
adjacency_df = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Step 1: Prepare data
transport_values = transport_df.set_index('borough')['Transport_value']

# Step 2: Define high/low thresholds (75th and 25th percentiles)
high_threshold = np.percentile(transport_values, 75)
low_threshold = np.percentile(transport_values, 25)

# Step 3: Calculate neighborhood means
neighbor_means = {}
for borough in transport_values.index:
    neighbors = adjacency_df[adjacency_df['borough'] == borough]['neighbor']
    neighbor_values = transport_values[neighbors].dropna()
    if len(neighbor_values) > 0:
        neighbor_means[borough] = neighbor_values.mean()
    else:
        neighbor_means[borough] = np.nan

# Step 4: Classify HH/LL spots
candidates = []
for borough in transport_values.index:
    if borough not in neighbor_means or np.isnan(neighbor_means[borough]):
        continue
    borough_value = transport_values[borough]
    neighbor_mean = neighbor_means[borough]

    # Check HH (high borough + high neighbors)
    if borough_value > high_threshold and neighbor_mean > high_threshold:
        candidates.append((borough, 'HH', borough_value, neighbor_mean))
    # Check LL (low borough + low neighbors)
    elif borough_value < low_threshold and neighbor_mean < low_threshold:
        candidates.append((borough, 'LL', borough_value, neighbor_mean))

# Step 5: Permutation test for significance (500 shuffles)
if candidates:
    observed_stats = []
    for borough, typ, borough_value, neighbor_mean in candidates:
        observed_stats.append((borough, typ, neighbor_mean))

    # Perform permutation test
    n_permutations = 500
    count_extreme = {borough: 0 for borough, _, _ in observed_stats}

    for _ in range(n_permutations):
        shuffled_values = np.random.permutation(transport_values.values)
        shuffled_series = pd.Series(shuffled_values, index=transport_values.index)

        for borough, typ, observed_mean in observed_stats:
            neighbors = adjacency_df[adjacency_df['borough'] == borough]['neighbor']
            neighbor_values = shuffled_series[neighbors].dropna()
            if len(neighbor_values) > 0:
                shuffled_mean = neighbor_values.mean()
                if typ == 'HH' and shuffled_mean >= observed_mean:
                    count_extreme[borough] += 1
                elif typ == 'LL' and shuffled_mean <= observed_mean:
                    count_extreme[borough] += 1

    # Calculate p-values
    significant_candidates = []
    for borough, typ, observed_mean in observed_stats:
        p_value = (count_extreme[borough] + 1) / (n_permutations + 1)  # +1 for observed
        if p_value < 0.05:
            significant_candidates.append((borough, typ, observed_mean, p_value))
else:
    significant_candidates = []

# Step 6: Output results
data_points_used = len(transport_values) - transport_values.isna().sum()
print(f"data_points_used = {data_points_used}")

if significant_candidates:
    final_output = []
    for borough, typ, observed_mean, p_value in significant_candidates:
        final_output.append(f"{borough} ({typ}, p-value={p_value:.4f})")
    print("FINAL ANSWER: " + ", ".join(final_output))
else:
    print("FINAL ANSWER: none")
